package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class)
@Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyHospitalDraftSubmitLocalDatabaseTest {
 @Autowired FeatureStore store;@Autowired com.fasterxml.jackson.databind.ObjectMapper json;@Autowired org.springframework.transaction.PlatformTransactionManager transactions;
 LegacyHospitalHistoryLocalDatabaseTest f;LegacyHospitalDraftSubmissionService service;
 @BeforeEach void setup(){f=new LegacyHospitalHistoryLocalDatabaseTest();f.store=store;f.setup();gate(true,"LEGACY");store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET SampleStatus=-2,CreateSampleId=0 WHERE ListDiagnosisProjectId=?",f.f.order);var drafts=new LegacyHospitalDraftService(store,f.f.access,f.service);var items=new LegacyHospitalDraftItemsService(store,f.f.access,f.service,drafts);service=new LegacyHospitalDraftSubmissionService(store,f.f.access,f.service,drafts,items);}
 void gate(boolean enabled,String mode){f.gate(store.encode(Map.of("enabled",true,"writeEnabled",true,"draftEnabled",true,"draftWriteEnabled",true,"draftSubmitEnabled",enabled,"previewVarietyMode",mode)));}
 LegacyHospitalDraftSubmissionService.Command command(){return new LegacyHospitalDraftSubmissionService.Command((int)f.f.hospital,(String)service.preview(f.f.order,(int)f.f.hospital).get("editToken"),"submit_"+UUID.randomUUID().toString().replace("-",""));}
 @Test void sourceSubmitChangesOnlyStatusAndAllowsEmptyOriginalDraftWithoutInventingIdentityOrAmount(){var before=new LinkedHashMap<>(store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.f.order));var c=command();assertEquals(true,service.preview(f.f.order,(int)f.f.hospital).get("writable"));service.submit(f.f.order,c);before.put("SampleStatus",0);assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.f.order));assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_order_extension WHERE order_id=?",Integer.class,f.f.order));service.submit(f.f.order,c);assertEquals(1,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_audit_record WHERE actor_user_id=? AND resource_type='LEGACY_HOSPITAL_DRAFT_SUBMIT' AND request_id=?",Integer.class,f.f.actor,c.requestKey()));}
 @Test void staleDetailsWrongScopeAndIndependentGateCannotSubmit(){var c=command();f.f.detail(f.f.test,"8.25",0,0);assertEquals(409,assertThrows(BusinessException.class,()->service.submit(f.f.order,c)).getCode());assertEquals(403,assertThrows(BusinessException.class,()->service.preview(f.f.order,2147483647)).getCode());var fresh=command();gate(false,"LEGACY");assertEquals(409,assertThrows(BusinessException.class,()->service.submit(f.f.order,fresh)).getCode());}
 @Test void previewExposesSourceVarietyReindexSeparatelyAndPendingDecisionBlocksWrite(){var fields=service.preview(f.f.order,(int)f.f.hospital);assertTrue(fields.containsKey("legacyVarietyName"));assertTrue(fields.containsKey("idVarietyName"));gate(true,"PENDING");assertEquals(false,service.preview(f.f.order,(int)f.f.hospital).get("writable"));assertEquals(409,assertThrows(BusinessException.class,()->service.submit(f.f.order,command())).getCode());}
 @Test void auditFailureRollsBackStateAndRetryRecovers(){var c=command();var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.f.order);var faulty=new FeatureStore(store.jdbc(),json){@Override public long insert(String sql,Object...args){if(sql.startsWith("INSERT INTO lin_audit_record"))throw new BusinessException(409,"owned submit audit failure");return super.insert(sql,args);}};var drafts=new LegacyHospitalDraftService(store,f.f.access,f.service);var broken=new LegacyHospitalDraftSubmissionService(faulty,f.f.access,f.service,drafts,new LegacyHospitalDraftItemsService(store,f.f.access,f.service,drafts));var tx=new org.springframework.transaction.support.TransactionTemplate(transactions);tx.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);var manager=(org.springframework.transaction.support.AbstractPlatformTransactionManager)transactions;boolean previous=manager.isNestedTransactionAllowed();manager.setNestedTransactionAllowed(true);try{assertThrows(BusinessException.class,()->tx.execute(status->broken.submit(f.f.order,c)));}finally{manager.setNestedTransactionAllowed(previous);}assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.f.order));service.submit(f.f.order,c);}
}
